paths.update(FULL_REPLACEMENTS)
paths.add("components/characters/ActiveShapeEffects.tsx")
edited={}
for rel in sorted(paths):
    q=root/rel
    if not q.exists(): raise SystemExit(f"STOP: missing expected file: {rel}")
    edited[rel]=q.read_text(encoding="utf-8")
for op in BASE_OPS:
    text=edited[op["path"]]; old=decode(op["old"]); new=decode(op["new"]); count=text.count(old)
    if count!=1: raise RuntimeError(f'{op["label"]}: expected exactly 1 match in {op["path"]}, found {count}')
    edited[op["path"]]=text.replace(old,new,1)
active_original=edited["components/characters/ActiveShapeEffects.tsx"]
if "getCharacterActiveShapeEffects" not in active_original: raise RuntimeError("ActiveShapeEffects.tsx does not match the expected current commit.")
edited["components/characters/ActiveShapeEffects.tsx"]=decode(BASE_ACTIVE)
for op in EXTRA_OPS:
    text=edited[op["path"]]; old=decode(op["old"]); new=decode(op["new"]); count=text.count(old)
    if count!=1: raise RuntimeError(f'{op["label"]}: expected exactly 1 match in {op["path"]}, found {count}')
    edited[op["path"]]=text.replace(old,new,1)
for rel,encoded in FULL_REPLACEMENTS.items(): edited[rel]=decode(encoded)
for rel in BASE_NEW:
    if (root/rel).exists(): raise SystemExit(f"STOP: patch target already exists: {rel}")
sql_path=root/"unified-effects-feats-dispel-migration.sql"
if sql_path.exists(): raise SystemExit("STOP: unified-effects-feats-dispel-migration.sql already exists.")
for rel,text in edited.items(): (root/rel).write_text(text,encoding="utf-8")
for rel,encoded in BASE_NEW.items():
    q=root/rel; q.parent.mkdir(parents=True,exist_ok=True); q.write_text(decode(encoded),encoding="utf-8")
sql_path.write_text(decode(SQL),encoding="utf-8")
